def transform_final(grid):
    H = len(grid)
    W = len(grid[0])

    result = [[0 for _ in range(W)] for _ in range(H)]

    # Find top cells
    top_cells = {}
    for c in range(W):
        if grid[0][c] != 0:
            top_cells[c] = grid[0][c]

    # Copy input (preserving outliers and background)
    for r in range(H):
        for c in range(W):
            result[r][c] = grid[r][c]

    # Build vertical columns from top cells
    for c, color in top_cells.items():
        for r in range(H):
            result[r][c] = color

    # Find horizontal fills (outliers creating fills toward matching vertical column)
    fill_regions = []  # list of (row, fill_start, fill_end, fill_color)
    for r in range(H):
        for c in range(W):
            val = result[r][c]
            if val != 0 and (r, c) not in [(0, cc) for cc in top_cells]:
                # Find matching vertical column
                vcol = None
                for col in range(W):
                    if col != c and col in top_cells and result[r][col] == val:
                        vcol = col
                        break

                if vcol is not None and vcol != c:
                    if vcol < c:
                        fill_start = vcol + 1
                        fill_end = c  # exclusive
                    else:
                        fill_start = c + 1
                        fill_end = vcol  # exclusive

                    # Record full fill region (including outlier cell position)
                    min_col = min(c, fill_start)
                    max_col = max(c, fill_end)

                    fill_regions.append((r, min_col, max_col, val))

                # Fill with outlier's color
                if vcol is not None and vcol != c:
                    if vcol < c:
                        for col in range(vcol + 1, c):
                            result[r][col] = val
                    else:
                        for col in range(c + 1, vcol):
                            result[r][col] = val

    # Now cut off vertical columns where horizontal fill occurs
    # For each vertical column c, find the row where it's covered by a horizontal fill
    # That vertical column should be cut at that row
    cut_row = {}  # column -> row where vertical column is cut

    for c in top_cells:
        row_covered = None
        for r0, fs, fe, fc in fill_regions:
            if fs <= c < fe:
                row_covered = r0
                break
        if row_covered is not None:
            cut_row[c] = row_covered

    # Build final result
    # First, set up base with input values and vertical columns
    final = [[0 for _ in range(W)] for _ in range(H)]
    for r in range(H):
        row = [0 for _ in range(W)]
        # Copy input
        for c in range(W):
            row[c] = grid[r][c]
        # Add vertical columns
        for c, color in top_cells.items():
            row[c] = color
        final[r] = row

    # Cut off vertical columns and replace with 0
    for c, color in cut_row.items():
        for r in range(cut_row[c] + 1, H):
            final[r][c] = 0

    return final

